/* @autogenerated */
import { signal } from '@angular/core';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { EntityImportComponent } from './entity-import.component';
import { EntityImportService } from './entity-import.service';
import { ImportDefinition, ImportJob, ImportSheet } from './entity-import.model';

const sheet = (rows: unknown[][], headers = ['Nombre', 'Correo', 'Activo', 'Estado', 'Clave']): ImportSheet => ({
  name: 'Datos',
  headers,
  rows: rows.map((cells, index) => ({ row: index + 2, cells })),
});

describe('EntityImportComponent', () => {
  let fixture: ComponentFixture<EntityImportComponent>;
  let component: EntityImportComponent;
  let service: jasmine.SpyObj<EntityImportService>;
  let job: ReturnType<typeof signal<ImportJob | null>>;
  let acl: Acl;
  let fixed: Record<string, { $ref: string }>;

  const definition = (extra: Partial<ImportDefinition<any>> = {}): ImportDefinition<any> => ({
    storageKey: 'test.items',
    scope: 'test',
    keys: ['name'],
    columns: [
      { field: 'uid', label: 'form.uid' },
      { field: 'name', label: 'form.name', required: true },
      { field: 'email', label: 'form.email', required: true },
      { field: 'active', label: 'form.active', type: 'boolean' },
      {
        field: 'status',
        label: 'form.status',
        type: 'enum',
        options: [
          { value: 'open', label: 'form.status.open' },
          { value: 'closed', label: 'form.status.closed' },
        ],
      },
      { field: 'secret', label: 'form.secret' },
      { field: 'tenant', label: 'form.tenant', type: 'reference' },
      { field: 'born', label: 'form.born', type: 'date' },
    ],
    sensitive: ['secret'],
    actions: {
      status: [
        { name: 'close', value: 'closed', run: () => of({}) },
        { name: 'open', value: 'open', run: () => of({}) },
      ],
    },
    target: {
      acl: () => of(acl),
      find: () => of([]),
      add: (item: any) => of(item),
      update: (item: any) => of(item),
      context: () => ({ fixed, defaults: {}, filtered: [] }),
    } as any,
    ...extra,
  });

  const create = (extra: Partial<ImportDefinition<any>> = {}) => {
    TestBed.overrideTemplate(EntityImportComponent, '');
    fixture = TestBed.createComponent(EntityImportComponent);
    fixture.componentRef.setInput('definition', definition(extra));
    fixture.detectChanges();
    component = fixture.componentInstance;
    return component;
  };

  beforeEach(() => {
    job = signal<ImportJob | null>(null);
    acl = {
      allows: [
        { name: 'create', allowed: true },
        { name: 'update', allowed: true },
        { name: 'close', allowed: true },
      ],
      fields: { noEditables: ['status'], noVisibles: ['secret'] },
    };
    fixed = { tenant: { $ref: 't1' } };
    service = jasmine.createSpyObj<EntityImportService>('EntityImportService', [
      'job',
      'isRunningHere',
      'canResume',
      'refresh',
      'start',
      'resume',
      'cancel',
      'clear',
    ]);
    service.job.and.returnValue(job);
    service.isRunningHere.and.returnValue(false);
    service.canResume.and.returnValue(false);
    TestBed.configureTestingModule({
      imports: [
        EntityImportComponent,
        TranslocoTestingModule.forRoot({
          langs: {
            en: {
              common: {
                import: {
                  mapping: { key: 'key', required: 'required', viaAction: 'by action' },
                  template: { fileName: 'plantilla.xlsx' },
                },
              },
            },
            'test/en': {
              form: { name: 'Nombre', email: 'Correo', active: 'Activo', status: 'Estado', secret: 'Clave' },
            },
          },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
          preloadLangs: true,
        }),
      ],
      providers: [{ provide: EntityImportService, useValue: service }],
    });
  });

  afterEach(() => TestBed.resetTestingModule());

  describe('columns', () => {
    it('offers the keys, the writable fields and the read-only ones an allowed action changes', () => {
      create();

      expect(component.aclLoaded()).toBeTrue();
      expect(component.columns().map((column) => column.field)).toEqual(['name', 'email', 'active', 'status', 'born']);
      expect(component.columns().find((column) => column.field === 'status')!.viaAction).toBeTrue();
    });

    it('takes out the fields fixed by the context and names the forbidden ones', () => {
      create();

      expect(component.fixedColumns().map((column) => column.field)).toEqual(['tenant']);
      expect(component.forbiddenLabels()).toBe('Clave');
    });

    it('does not offer a read-only field without an allowed action', () => {
      acl = { ...acl, allows: [{ name: 'create', allowed: true }] };
      create();

      expect(component.columns().map((column) => column.field)).not.toContain('status');
      expect(component.canUpdate()).toBeFalse();
      expect(component.canCreate()).toBeTrue();
    });

    it('allows everything with allAllowed', () => {
      acl = { allAllowed: true };
      fixed = {};
      create();

      expect(component.columns().map((column) => column.field)).toContain('secret');
      expect(component.canUpdate()).toBeTrue();
    });

    it('labels the options of the field selector', () => {
      create();
      const [name, email, active, status] = component.columns();

      expect(component.optionText(name)).toBe(`${name.text} (key)`);
      expect(component.optionText(email)).toBe(`${email.text} (required)`);
      expect(component.optionText(active)).toBe(active.text);
      expect(component.optionText(status)).toBe(`${status.text} (by action)`);
    });
  });

  describe('mapping', () => {
    it('proposes a header for each field and checks the keys', () => {
      create();
      expect(component.mapping()).toEqual({});

      component.sheets.set([sheet([['Ana', 'ana@x', 'sí', 'open', 's1']])]);

      expect(component.mapping()['name']).toBe(0);
      expect(component.mapping()['email']).toBe(1);
      expect(component.missingKeys()).toEqual([]);
      expect(component.canStart()).toBeTrue();
      expect(component.headers().map((header) => header.text)).toEqual([
        'Nombre',
        'Correo',
        'Activo',
        'Estado',
        'Clave',
      ]);
      expect(component.fieldAt()[0]).toBe('name');
      expect(component.hasBoolean()).toBeTrue();
      expect(component.hasDate()).toBeFalse();
    });

    it('can not start without the key column', () => {
      create();
      component.sheets.set([sheet([['ana@x']], ['Correo'])]);

      expect(component.missingKeys().map((column) => column.field)).toEqual(['name']);
      expect(component.canStart()).toBeFalse();
      expect(component.unmappedLabels()).toContain('Nombre');
    });

    it('marks the required fields that do not come in the Excel', () => {
      create();
      component.sheets.set([sheet([['Ana']], ['Nombre'])]);
      expect(component.missingRequired().map((column) => column.field)).toEqual(['email']);
    });

    it('does not miss a required field with a default value', () => {
      create({ defaults: () => ({ email: 'none' }) });
      component.sheets.set([sheet([['Ana']], ['Nombre'])]);
      expect(component.missingRequired()).toEqual([]);
    });

    it('moves a header from one field to another', () => {
      create();
      component.sheets.set([sheet([['Ana', 'ana@x']], ['Nombre', 'Correo'])]);

      component.assignHeader(1, 'name');

      expect(component.mapping()['name']).toBe(1);
      expect(component.mapping()['email']).toBeNull();
      component.assignHeader(1, null);
      expect(component.mapping()['name']).toBeNull();
      component.assignHeader(1, null);
      expect(component.mapping()['name']).toBeNull();
    });
  });

  describe('preview', () => {
    it('checks each row: unreadable cells and empty keys', () => {
      create();
      component.sheets.set([
        sheet([
          ['Ana', 'ana@x', 'sí', 'open', 's1'],
          [null, 'b@x', 'quizá', 'open', 's2'],
        ]),
      ]);

      const [good, bad] = component.checks();
      expect(good.messages).toEqual([]);
      expect(bad.messages.map((message) => message.key)).toContain('common.import.error.missingKey');
      expect(bad.messages.length).toBe(2);
      expect(component.failingRows()).toBe(1);
    });

    it('reads other words for yes and no', () => {
      create();
      component.sheets.set([sheet([['Ana', 'ana@x', 'vale', 'open', 's1']])]);
      expect(component.failingRows()).toBe(1);

      component.trueText.set('vale, ok;');

      expect(component.parsing().trueWords).toEqual(['vale', 'ok']);
      expect(component.failingRows()).toBe(0);
    });

    it('shows only the rows with errors and pages the preview', () => {
      create();
      const rows = Array.from({ length: 60 }, (_, i) => [i % 2 ? `item-${i}` : null, 'x@x']);
      component.sheets.set([sheet(rows, ['Nombre', 'Correo'])]);

      expect(component.preview().length).toBe(50);
      expect(component.hiddenRows()).toBe(10);
      component.showMore();
      expect(component.hiddenRows()).toBe(0);
      component.onlyErrors.set(true);
      expect(component.preview().length).toBe(30);
    });

    it('shows the text of each cell, masking the sensitive ones', () => {
      acl = { allAllowed: true };
      fixed = {};
      create();
      component.sheets.set([sheet([['Ana', new Date(2024, 0, 2), ' ', null, 'hidden']])]);
      const row = component.sheet()!.rows[0];

      expect(component.cellText(row, 0)).toBe('Ana');
      expect(component.cellText(row, 1)).toBe(new Date(2024, 0, 2).toLocaleString());
      expect(component.cellText(row, 2)).toBe('');
      expect(component.cellText(row, 3)).toBe('');
      expect(component.cellText(row, 4)).toBe('••••••');
    });

    it('describes the messages one per line', () => {
      create();

      expect(component.describe([{ key: 'one' }, { key: 'two' }])).toBe('one\ntwo');
      expect(component.describe(undefined)).toBe('');
    });
  });

  describe('file', () => {
    it('reads the sheets of a workbook and selects the first one with rows', async () => {
      create();
      const XLSX = await import('xlsx');
      const book = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([]), 'Vacía');
      XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([['Nombre'], ['Ana']]), 'Datos');
      const file = new File([XLSX.write(book, { type: 'array', bookType: 'xlsx' })], 'items.xlsx');
      const input = { files: [file], value: 'items.xlsx' };

      await component.read({ target: input } as any);

      expect(input.value).toBe('');
      expect(component.fileName()).toBe('items.xlsx');
      expect(component.sheetIndex()).toBe(1);
      expect(component.sheet()!.rows.length).toBe(1);
      expect(component.reading()).toBeFalse();
    });

    it('marks the reading as failed with a file it can not read', async () => {
      create();
      const file = { name: 'bad.xlsx', arrayBuffer: () => Promise.reject(new Error('broken')) } as any;

      await component.read({ target: { files: [file], value: '' } } as any);

      expect(component.readFailed()).toBeTrue();
      expect(component.reading()).toBeFalse();
    });

    it('does nothing without a file', async () => {
      create();

      await component.read({ target: { files: [], value: '' } } as any);

      expect(component.reading()).toBeFalse();
      expect(component.fileName()).toBe('');
    });

    it('downloads an empty template with the columns it can import', async () => {
      create();
      // XLSX guarda con `saveAs` si existe (lo deja file-saver): se fija uno para no depender del orden de los specs
      const saveAs = jasmine.createSpy('saveAs');
      (window as any).saveAs = saveAs;
      try {
        await component.downloadTemplate();
      } finally {
        delete (window as any).saveAs;
      }

      expect(component.downloading()).toBeFalse();
      expect(saveAs).toHaveBeenCalledWith(jasmine.any(Blob), 'plantilla.xlsx');
    });
  });

  describe('job', () => {
    it('starts the import with the plan and goes back to choose a file', () => {
      create();
      component.fileName.set('items.xlsx');
      component.sheets.set([sheet([['Ana', 'ana@x', 'sí', 'closed', 's1']])]);

      component.start();

      const [, plan] = service.start.calls.mostRecent().args;
      expect(plan.fileName).toBe('items.xlsx');
      expect(plan.rows.length).toBe(1);
      expect(plan.allowedActions).toEqual(['close']);
      expect(plan.canCreate).toBeTrue();
      expect(component.sheets()).toEqual([]);
    });

    it('does not start when it can not', () => {
      create();

      component.start();

      expect(service.start).not.toHaveBeenCalled();
    });

    it('resumes, cancels and clears its job', () => {
      create();

      component.resume();
      component.cancel();
      component.restart();

      expect(service.resume).toHaveBeenCalled();
      expect(service.cancel).toHaveBeenCalledWith('test.items');
      expect(service.clear).toHaveBeenCalledWith('test.items');
    });

    it('sums up the progress and the outcomes of the job', () => {
      create();
      job.set({
        key: 'test.items',
        fileName: 'items.xlsx',
        status: 'running',
        startedAt: '',
        updatedAt: '',
        total: 4,
        processed: 2,
        created: 1,
        updated: 0,
        failed: 1,
        outcomes: [
          { row: 2, display: 'Ana', result: 'created', messages: [{ key: 'warn' }] },
          { row: 3, display: 'Bea', result: 'failed' },
        ],
      } as ImportJob);

      expect(component.progress()).toBe(50);
      expect(component.failures().length).toBe(1);
      expect(component.successes().length).toBe(1);
      expect(component.warnings().length).toBe(1);
      expect(component.runningElsewhere()).toBeTrue();
    });

    it('checks every few seconds an import running in another tab', () => {
      jasmine.clock().install();
      try {
        create();
        job.set({ status: 'running', total: 0, outcomes: [] } as any);
        fixture.detectChanges();

        jasmine.clock().tick(10_000);

        expect(service.refresh).toHaveBeenCalledWith('test.items');
      } finally {
        jasmine.clock().uninstall();
      }
    });
  });
});
